from moler.device.unixremote3 import UnixRemote3


class UteLinuxRemote3(UnixRemote3):
    """UnixRemote with specific Nokia commands and events."""

    _supported_states = (UnixRemote3.unix_remote, UnixRemote3.unix_remote_root, UnixRemote3.proxy_pc, UnixRemote3.unix_local, UnixRemote3.unix_local_root)

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        if state in UteLinuxRemote3._supported_states:
            available = {
                UteLinuxRemote3.cmds: ["moler.cmd.unix", "ta_moler.cmd.ute_linux"],
                UteLinuxRemote3.events: ["moler.events.shared", "moler.events.unix"],
            }
            return available[observer]
        return []
